import test from 'node:test';
import assert from 'node:assert/strict';
import { RATES, convert, formatMoney } from '../src/money.js';

// RATES constant
test('RATES has EUR at 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES has USD at 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES has GBP at 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

// convert() function - basic
test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD multiplies by rate', () => {
  const result = convert(10000, 'USD'); // 100 EUR

  assert.equal(result.ok, true);
  // 10000 * 1.085 = 10850
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP multiplies by rate', () => {
  const result = convert(10000, 'GBP'); // 100 EUR

  assert.equal(result.ok, true);
  // 10000 * 0.8425 = 8425
  assert.equal(result.value, 8425);
});

test('convert returns integer cents', () => {
  const result = convert(100, 'USD');

  assert.ok(Number.isInteger(result.value));
});

test('convert rounds to nearest cent', () => {
  const result = convert(123, 'USD'); // 1.23 EUR

  assert.ok(Number.isInteger(result.value));
  // 123 * 1.085 = 133.455 → rounds to 133
  assert.equal(result.value, 133);
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert with large amount', () => {
  const result = convert(1000000000, 'USD'); // 10 million EUR

  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000000);
});

// convert() - edge cases
test('convert with case-sensitive currency', () => {
  const result = convert(10000, 'eur');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert USD then back to EUR approximately matches original', () => {
  const original = 10000;
  const toUsd = convert(original, 'USD');
  const backToEur = Math.round(toUsd.value / 1.085);

  assert.equal(backToEur, original);
});

test('convert GBP then back to EUR approximately matches original', () => {
  const original = 10000;
  const toGbp = convert(original, 'GBP');
  const backToEur = Math.round(toGbp.value / 0.8425);

  assert.equal(backToEur, original);
});

// formatMoney() - EUR
test('formatMoney EUR returns plain number', () => {
  const result = formatMoney(10000, 'EUR');

  assert.equal(result, '100.00');
});

test('formatMoney EUR no currency symbol', () => {
  const result = formatMoney(5000, 'EUR');

  assert.ok(!result.includes('€'));
  assert.ok(!result.includes('$'));
});

// formatMoney() - USD
test('formatMoney USD returns $ symbol', () => {
  const result = formatMoney(10000, 'USD');

  assert.ok(result.startsWith('$'));
});

test('formatMoney USD converts and formats', () => {
  const result = formatMoney(10000, 'USD');

  // 10000 * 1.085 = 10850 cents = $108.50
  assert.equal(result, '$108.50');
});

test('formatMoney USD with small amount', () => {
  const result = formatMoney(100, 'USD');

  assert.equal(result, '$1.09'); // 100 * 1.085 = 108.5 → 109 cents
});

test('formatMoney USD with 2 decimal places', () => {
  const result = formatMoney(12345, 'USD');

  assert.ok(/\$\d+\.\d{2}/.test(result));
});

// formatMoney() - GBP
test('formatMoney GBP returns £ symbol', () => {
  const result = formatMoney(10000, 'GBP');

  assert.ok(result.startsWith('£'));
});

test('formatMoney GBP converts and formats', () => {
  const result = formatMoney(10000, 'GBP');

  // 10000 * 0.8425 = 8425 cents = £84.25
  assert.equal(result, '£84.25');
});

test('formatMoney GBP with 2 decimal places', () => {
  const result = formatMoney(10000, 'GBP');

  assert.ok(/£\d+\.\d{2}/.test(result));
});

// formatMoney() - edge cases
test('formatMoney zero amount', () => {
  const usd = formatMoney(0, 'USD');
  const gbp = formatMoney(0, 'GBP');
  const eur = formatMoney(0, 'EUR');

  assert.equal(usd, '$0.00');
  assert.equal(gbp, '£0.00');
  assert.equal(eur, '0.00');
});

test('formatMoney unknown currency returns plain number', () => {
  const result = formatMoney(10000, 'JPY');

  assert.equal(result, '100.00');
});

test('formatMoney case sensitive', () => {
  const result = formatMoney(10000, 'usd');

  // 'usd' is not in RATES, so fallback to plain number
  assert.equal(result, '100.00');
});

test('formatMoney large amount USD', () => {
  const result = formatMoney(1000000000, 'USD');

  assert.ok(result.startsWith('$'));
  assert.ok(/\$\d+\.\d{2}/.test(result));
});

test('formatMoney small USD amount rounds correctly', () => {
  const result = formatMoney(50, 'USD'); // 0.50 EUR

  // 50 * 1.085 = 54.25 → 54 cents = $0.54
  assert.equal(result, '$0.54');
});

// Consistency tests
test('convert and format are consistent', () => {
  const converted = convert(10000, 'USD');
  const formatted = formatMoney(10000, 'USD');

  // converted.value should be 10850
  // formatted should be $108.50 which is 10850 cents
  assert.equal(converted.value, 10850);
  assert.equal(formatted, '$108.50');
});

test('all currencies available in RATES', () => {
  assert.ok(RATES.EUR !== undefined);
  assert.ok(RATES.USD !== undefined);
  assert.ok(RATES.GBP !== undefined);
});

test('RATES are positive numbers', () => {
  assert.ok(RATES.EUR > 0);
  assert.ok(RATES.USD > 0);
  assert.ok(RATES.GBP > 0);
});

// Multiple conversions
test('convert multiple currencies from same amount', () => {
  const eur = convert(50000, 'EUR');
  const usd = convert(50000, 'USD');
  const gbp = convert(50000, 'GBP');

  assert.equal(eur.ok, true);
  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);

  // USD should be more than EUR, GBP should be less
  assert.ok(usd.value > eur.value);
  assert.ok(gbp.value < eur.value);
});

test('formatMoney multiple currencies from same amount', () => {
  const eur = formatMoney(50000, 'EUR');
  const usd = formatMoney(50000, 'USD');
  const gbp = formatMoney(50000, 'GBP');

  // Should all be valid formatted strings
  assert.ok(/\d+\.\d{2}/.test(eur));
  assert.ok(/\$\d+\.\d{2}/.test(usd));
  assert.ok(/£\d+\.\d{2}/.test(gbp));

  // USD amount should be higher than EUR amount
  const eurAmount = parseFloat(eur);
  const usdAmount = parseFloat(usd.slice(1));
  assert.ok(usdAmount > eurAmount);
});

test('convert preserves precision through rounding', () => {
  // Test that rounding is consistent
  const amounts = [1, 10, 100, 1000, 10000, 100000];

  for (const amount of amounts) {
    const result = convert(amount, 'USD');
    assert.equal(result.ok, true);
    assert.ok(Number.isInteger(result.value));
  }
});

test('formatMoney consistent decimal formatting', () => {
  const amounts = [1, 10, 100, 1000, 10000];

  for (const amount of amounts) {
    const formatted = formatMoney(amount, 'USD');
    // Should always have exactly 2 decimal places
    assert.ok(/\$\d+\.\d{2}/.test(formatted));
  }
});
EOF

